intro.body:
用 Euler-Maruyama 求解 SDE，并写出逆向 SDE 与概率流 ODE 的漂移。

```python
class VPSDE:
    def __init__(self, beta_min=0.1, beta_max=20.0):
        self.beta_min, self.beta_max = beta_min, beta_max
    def beta(self, t):
        return self.beta_min + t * (self.beta_max - self.beta_min)
    def forward_drift(self, x, t):
        return -0.5 * self.beta(t) * x
    def diffusion_coeff(self, t):
        return self.beta(t) ** 0.5
    def reverse_drift(self, x, t, score_fn):
        score = score_fn(x, t)
        return self.forward_drift(x, t) - self.beta(t) * score
    def probability_flow_drift(self, x, t, score_fn):
        score = score_fn(x, t)
        return self.forward_drift(x, t) - 0.5 * self.beta(t) * score
def em_step(x, t, drift_fn, diffusion_fn, dt):
    drift = drift_fn(x, t)
    g = diffusion_fn(t)
    noise = torch.randn_like(x)
    return x + drift * dt + g * dt**0.5 * noise
```
